324	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
325		\uses{def:povm-distance, def:povm-conventions}
326		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
327		\begin{align*}
328			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
329			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
330		\end{align*}
331		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
332		\[
333			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
334		\]
335	\end{lemma}
336	\begin{proof}
337		\uses{fact:add-a-proj, fact:triangle}
338		Applying Lemma~\ref{fact:add-a-proj} to $C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,c}$ with the multiplier family $\{A^x_{a,\,b} \ot \Id_B\}$, we have
339		\begin{equation}\label{eq:commutation-analysis-1}
340			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
341		\end{equation}
342		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
343		\begin{equation}\label{eq:commutation-analysis-2}
344			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
345		\end{equation}
346		Combining \eqref{eq:commutation-analysis-1} and \eqref{eq:commutation-analysis-2} via Lemma~\ref{fact:triangle},
347		\begin{equation}\label{eq:commutation-analysis-3}
348			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
349		\end{equation}
350		A symmetric argument gives
351		\begin{equation}\label{eq:commutation-analysis-4}
352			C^x_{a,\,c}\, A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
353		\end{equation}
354		The claim follows by subtracting \eqref{eq:commutation-analysis-3} and \eqref{eq:commutation-analysis-4}.
355	\end{proof}
