 319	\section{Applying the classical low-degree test}
 320	\label{sec:apply-ldt}
 321	
 322	The combined point and line measurements of the previous two sections are next
 323	merged into a single measurement returning a pair of global polynomials that
 324	encode the $X$-basis and the $Z$-basis information simultaneously. This is
 325	done by encoding the pair as one polynomial in $2m+2$ variables and invoking
 326	the quantum soundness of the classical low individual degree test
 327	(Theorem~\ref{lem:ld-soundness}). The instantiation at dimension $2m+2$
 328	requires that $2m+2$ divide $q$; the statements below carry this hypothesis
 329	explicitly, and Remark~\ref{rem:qld-4-7-divisibility} discusses its
 330	relationship to the admissibility of $(q,m,d)$.
 331	
 332	\begin{definition}[The combining map]
 333		\label{def:combine-map}
 334		\uses{def:polyfunc, def:line}
 335		For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
 336		$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
 337		\[
 338			\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
 339			= \alpha f(x) + \beta g(z)\,,
 340			\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
 341			\beta \in \F_q\,.
 342		\]
 343		The combining map is also defined for polynomials restricted to lines.
 344		Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
 345		$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
 346		$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
 347		lines in $\F_q^m$ such that for every point
 348		$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
 349		$z \in \ell_Z$. Then for any two polynomials
 350		$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
 351		$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
 352		\begin{equation}
 353			\label{eq:combine-lines}
 354			\mathrm{combine}_{f,g}(u + t \cdot v)
 355			= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
 356			+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
 357			\qquad t \in \F_q\,.
 358		\end{equation}
 359		The degree bound holds because $f$ and $g$, restricted to lines, are
 360		polynomials of degree at most $md$ in the line parameter, and each is
 361		multiplied by an affine factor of degree at most one.
 362	\end{definition}
 363	
 364	\begin{lemma}[Combined point measurement on the extended coordinates]
 365		\label{lem:qld-4-12}
 366		\uses{lem:qld-4-10, def:expanded-state, def:expanded-point-measurement,
 367			def:povm-distance, def:symmetric-equivalents}
 368		For all $x, z \in \F_q^m$, $\alpha, \beta \in \F_q$, and
 369		$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there exists a
 370		projective measurement
 371		$\{\hat{Q}^{x,z,\alpha,\beta}_{c}\}_{c \in \F_q}$ acting on
 372		$\hilb \ot (\C^q)^{\ot n}$ such that the following holds, where
 373		$\delta_Q$ is the function of Lemma~\ref{lem:qld-4-10}:
 374		\begin{enumerate}
 375			\item (\textbf{Self-consistency}) On average over uniformly random
 376			$(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
 377			\begin{equation}
 378				\label{eq:qld-4-12-self-cons}
 379				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
 380				\approx_{\delta_Q}
 381				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{B}\mathsf{A}''}\,.
 382			\end{equation}
 383			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly
 384			random $(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
 385			\begin{gather}
 386				\label{eq:qld-4-12-cons-m-hat}
 387				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
 388				\approx_{\delta_Q}
 389				\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
 390				\hat{M}^{(\mathrm{Point},X),x}_{a} \,
 391				\hat{M}^{(\mathrm{Point},Z),z}_{b}
 392				\Big)_{\mathsf{B}\mathsf{A}''}\,, \\
 393				\label{eq:qld-4-12-cons-m-hat2}
 394				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
