 396				\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
 397				\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
 398				\hat{M}^{(\mathrm{Point},X),x}_{a}
 399				\Big)_{\mathsf{B}\mathsf{A}''}\,.
 400			\end{gather}
 401		\end{enumerate}
 402		Furthermore, all symmetric equivalents of these approximations also hold.
 403	\end{lemma}
 404	\begin{proof}
 405		\uses{lem:qld-4-10, fact:data-processing}
 406		Define
 407		$\hat{Q}^{x,z,\alpha,\beta}_{c}
 408		= \sum_{a,b \,:\, \alpha a + \beta b = c} \hat{Q}^{x,z}_{a,b}$,
