180	\begin{definition}[Distance between states]\label{def:state-distance}
181		Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
182		\[
183			\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
184		\]
185		The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
186	\end{definition}
187	
188	\begin{definition}[Consistency between POVMs]\label{def:consistency}
189		\uses{def:povm-conventions, def:state-distance}
190		Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H_A \ot \mathcal H_B$ be a quantum state, and for all $x \in \mathcal X$ let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. We write
191		\[
192			A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a
193		\]
194		on state $\ket{\psi}$ and distribution $\mu$ if
195		\[
196			\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
197		\]
198		In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
199	\end{definition}
200	
201	A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.
202	
203	\begin{definition}[Distance between POVMs]\label{def:povm-distance}
204		\uses{def:povm-conventions, def:state-distance}
205		Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}$ and $\{N^x_a\}$ be two POVMs on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
206		\[
207			\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
208		\]
209		and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance.
210	\end{definition}
211	
212	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
213		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
214		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
215		\begin{enumerate}
216			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
217			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
218		\end{enumerate}
219	\end{definition}
220	
221	\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
222		Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. Any explicit quantitative version of the present relations therefore retains the constants absorbed into the $O(\cdot)$; for instance, the triangle inequality of Lemma~\ref{fact:triangle} carries a factor $2$ inside the $O(\cdot)$.
223	\end{remark}
224	
225	We record several useful facts about the consistency measure and the state-dependent distance. For the statements imported without proof, readers are referred to Sections~4.4 and~4.5 of \cite{Natarajan2018NEEXP}.
226	
227	\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
228		\uses{def:consistency, def:povm-distance}
229		For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
230		\begin{enumerate}
231			\item If $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$.
232			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements, then $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$.
233			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
234		\end{enumerate}
235	\end{lemma}
236	\begin{proof}
237		Stated in the source without proof; these are Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. For the first item, expand each term $\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \rVert^2$ and use $ (A^x_a)^2 \le A^x_a$, $(B^x_a)^2 \le B^x_a$ together with completeness of the two POVMs: summing over $a$ and averaging over $x$ leaves exactly twice the off-diagonal mass, which is $O(\delta)$ by hypothesis. For the converse items, write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$ and use projectivity of both families, or of one family combined with the Cauchy--Schwarz inequality; the latter route costs a square root in the error.
238	\end{proof}
239	
240	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
241		\uses{def:povm-distance}
242		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
243	\end{lemma}
244	\begin{proof}
245		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
246		\begin{align*}
247			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
